const items = $input.all();
const out = [];

// Function to detect MIME type from binary data (file signatures)
function detectMimeTypeFromBuffer(buffer) {
  if (buffer.length < 12) return 'application/octet-stream';

  // ISO BMFF/MP4/M4A
  if (buffer.slice(4, 8).toString('ascii') === 'ftyp') {
    const brand = buffer.slice(8, 12).toString('ascii');
    if (brand === 'qt  ' || brand === 'moov') return 'video/quicktime';
    if (['mp42','isom','avc1','iso2'].includes(brand)) return 'video/mp4';
    if (['M4A ','M4B ','mp41'].includes(brand)) return 'audio/mp4';
  }

  // WAV (RIFF....WAVE)
  if (buffer.slice(0, 4).toString('ascii') === 'RIFF' &&
      buffer.slice(8, 12).toString('ascii') === 'WAVE') return 'audio/wav';

  // AVI
  if (buffer.slice(0, 4).toString('ascii') === 'RIFF' &&
      buffer.slice(8, 12).toString('ascii') === 'AVI ') return 'video/x-msvideo';

  // WebM/Matroska
  if (buffer.length >= 4 && buffer.readUInt32BE(0) === 0x1a45dfa3) return 'video/webm';

  // FLAC
  if (buffer.slice(0, 4).toString('ascii') === 'fLaC') return 'audio/flac';

  // OGG container (may be Opus/Vorbis)
  if (buffer.slice(0, 4).toString('ascii') === 'OggS') {
    // Try to detect Opus
    if (buffer.includes(Buffer.from('OpusHead'))) return 'audio/opus';
    return 'audio/ogg';
  }

  // MP3: ID3 header or MPEG frame sync
  if (buffer.slice(0, 3).toString('ascii') === 'ID3') return 'audio/mpeg';
  const b0 = buffer[0], b1 = buffer[1];
  if (b0 === 0xff && (b1 & 0xe0) === 0xe0) return 'audio/mpeg';

  // AAC ADTS
  if (b0 === 0xff && (b1 & 0xf6) === 0xf0) return 'audio/aac';

  return 'application/octet-stream';
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // Get the binary property name (usually 'data' but could be different)
  const binaryKey = Object.keys(item.binary || {})[0];

  if (!binaryKey) {
    continue;
  }

  const binaryData = item.binary[binaryKey];

  // Extract input information
  const inputFilename = binaryData.fileName || 'unknown';
  let contentType = binaryData.mimeType || 'application/octet-stream';

  // Get actual file size in bytes from the buffer
  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryKey);
  const fileSizeBytes = buffer.length;

  // Detect MIME type from binary data if it's the default
  if (contentType === 'application/octet-stream') {
    contentType = detectMimeTypeFromBuffer(buffer);
  }

  // Get file extension from filename
  const inputExt = inputFilename.split('.').pop() || '';
  const base = inputFilename.replace(/\.[^/.]+$/, '') || inputFilename;

  // Generate date prefix (e.g., YYYY-MM-DD)
  const now = new Date();
  const datePrefix = now.toISOString().split('T')[0]; // Format: YYYY-MM-DD

  // Determine output extension (you can customize this logic)
  const outputExt = inputExt; // Or set to your desired extension

  // Create output filename
  const outputFilenameNoDate = `${base}.${outputExt}`;
  const outputFilename = `${datePrefix}-${outputFilenameNoDate}`;

  // Update binary data with detected mimeType
  const updatedBinary = {
    ...item.binary,
    [binaryKey]: {
      ...item.binary[binaryKey],
      mimeType: contentType
    }
  };

  out.push({
    json: {
      // input
      filename: inputFilename,
      contentType,
      fileSizeBytes,
      base,
      // output
      datePrefix,
      outputExt,
      outputFilenameNoDate,
      outputFilename
    },
    binary: updatedBinary // Preserve binary data with updated mimeType
  });
}

return out;
